-- Bổ sung Bài 24-25 (nối tiếp Bài 1-23 đã có) và gắn từ vựng/kanji mới vào
-- đúng bài học theo khung Minna no Nihongo Shokyu I, dựa trên danh sách từ mới
-- theo từng bài được tái hiện từ trí nhớ (không tra cứu được nguồn gốc chính
-- thức trong phiên này). Chỉ những từ/kanji khớp được chính xác (so khớp
-- chuỗi) với dữ liệu đã có trong DB mới được gắn bài; phần còn lại (đa số từ
-- vựng mới, vì kho từ MNN lõi ít hơn nhiều so với 1276 từ đã trích từ nhiều
-- PDF) vẫn còn trong DB nhưng CHƯA gắn bài cụ thể — vẫn dùng được qua tìm
-- kiếm/ôn tập/quiz. Kanji được gắn vào bài sớm nhất mà một từ chứa kanji đó
-- xuất hiện (suy luận gián tiếp, không phải theo sách Kanji riêng của MNN).
-- Độ tin cậy: Bài 1-13 cao; Bài 14-25 thấp hơn do ít căn cứ hơn — nên coi là
-- gợi ý tổ chức ban đầu, có thể cần người biết giáo trình rà soát lại.

insert into lessons (id, level_id, title, description, order_index)
select v.id, (select id from jlpt_levels where code = 'N5'), v.title, null, v.order_index
from (values
  ('f8a83cc6-d5af-5970-9c9c-6b4e35ce9184'::uuid, 'Bài 24 — Giả định, tuy nhiên', 24),
  ('c0c2afb4-5fa7-5844-a60a-e2b01ac4fb60'::uuid, 'Bài 25 — Thể bị động', 25)
) as v(id, title, order_index)
on conflict (id) do update set title = excluded.title;

